import{_ as e,o,c as t,a2 as r}from"./chunks/framework.CAKCj7G0.js";const u=JSON.parse('{"title":"LinkedHashMap","description":"","frontmatter":{},"headers":[],"relativePath":"Java/Java/集合/Map/LinkedHashMap.md","filePath":"Java/Java/集合/Map/LinkedHashMap.md","lastUpdated":1762838572000}'),l={name:"Java/Java/集合/Map/LinkedHashMap.md"};function i(n,a,d,s,h,c){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="linkedhashmap" tabindex="-1">LinkedHashMap <a class="header-anchor" href="#linkedhashmap" aria-label="Permalink to &quot;LinkedHashMap&quot;">​</a></h1><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>LinkedHashMap</strong> 是 Java 集合框架中 <code>HashMap</code> 的子类，它在保持哈希表高效查找性能的同时，通过维护一个双向链表来保证元素的迭代顺序。该实现结合了哈希表和链表的优点，既提供了快速的查找能力，又保证了元素的有序性。</p><h3 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h3><ul><li><strong>顺序保证</strong>：可以维护元素的插入顺序或访问顺序</li><li><strong>继承关系</strong>：继承自 <code>HashMap</code>，完全支持 <code>Map</code> 接口的所有操作</li><li><strong>线程安全性</strong>：非线程安全，多线程环境下需要额外同步</li><li><strong>键值限制</strong>：允许使用 null 键和 null 值</li><li><strong>性能特点</strong>：查找操作性能与 <code>HashMap</code> 相当，但维护顺序会带来少量性能开销</li></ul><h2 id="_2-底层数据结构" tabindex="-1">2. 底层数据结构 <a class="header-anchor" href="#_2-底层数据结构" aria-label="Permalink to &quot;2. 底层数据结构&quot;">​</a></h2><h3 id="_2-1-数据结构组成" tabindex="-1">2.1 数据结构组成 <a class="header-anchor" href="#_2-1-数据结构组成" aria-label="Permalink to &quot;2.1 数据结构组成&quot;">​</a></h3><p>LinkedHashMap 采用<strong>哈希表 + 双向链表</strong>的混合结构：</p><ul><li><strong>哈希表</strong>：继承自 HashMap，使用数组存储桶，每个桶内可能是链表或红黑树结构，用于快速定位键值对</li><li><strong>双向链表</strong>：额外维护的链表结构，用于按特定顺序（插入顺序或访问顺序）连接所有节点</li></ul><p>这种结构设计使得 LinkedHashMap 能够在 O(1) 时间复杂度内完成查找操作，同时保证元素的有序迭代。</p><h3 id="_2-2-节点设计" tabindex="-1">2.2 节点设计 <a class="header-anchor" href="#_2-2-节点设计" aria-label="Permalink to &quot;2.2 节点设计&quot;">​</a></h3><p>LinkedHashMap 的节点类扩展了 HashMap 的节点类，增加了维护双向链表所需的前后指针：</p><ul><li>每个节点包含指向前后节点的引用（before 和 after）</li><li>这些引用与哈希表结构中的 next 指针并存，但用途不同：next 用于解决哈希冲突，before/after 用于维护元素顺序</li></ul><h2 id="_3-核心参数与构造函数" tabindex="-1">3. 核心参数与构造函数 <a class="header-anchor" href="#_3-核心参数与构造函数" aria-label="Permalink to &quot;3. 核心参数与构造函数&quot;">​</a></h2><h3 id="_3-1-核心参数" tabindex="-1">3.1 核心参数 <a class="header-anchor" href="#_3-1-核心参数" aria-label="Permalink to &quot;3.1 核心参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>accessOrder</td><td>false</td><td>排序模式控制参数，false 表示维护插入顺序，true 表示维护访问顺序</td></tr></tbody></table><h3 id="_3-2-构造函数" tabindex="-1">3.2 构造函数 <a class="header-anchor" href="#_3-2-构造函数" aria-label="Permalink to &quot;3.2 构造函数&quot;">​</a></h3><p>LinkedHashMap 提供了多种构造函数以满足不同的初始化需求：</p><ul><li><strong>无参构造</strong>：创建一个默认初始容量（16）、默认负载因子（0.75）的 LinkedHashMap，默认维护插入顺序</li><li><strong>指定初始容量构造</strong>：创建具有指定初始容量的 LinkedHashMap</li><li><strong>指定初始容量和负载因子构造</strong>：创建具有指定初始容量和负载因子的 LinkedHashMap</li><li><strong>指定初始容量、负载因子和排序模式构造</strong>：最灵活的构造方式，可以控制是否维护访问顺序</li><li><strong>Map 集合构造</strong>：通过已有的 Map 集合创建 LinkedHashMap</li></ul><h2 id="_4-双向链表维护机制" tabindex="-1">4. 双向链表维护机制 <a class="header-anchor" href="#_4-双向链表维护机制" aria-label="Permalink to &quot;4. 双向链表维护机制&quot;">​</a></h2><h3 id="_4-1-链表维护原理" tabindex="-1">4.1 链表维护原理 <a class="header-anchor" href="#_4-1-链表维护原理" aria-label="Permalink to &quot;4.1 链表维护原理&quot;">​</a></h3><p>LinkedHashMap 通过重写 HashMap 中定义的回调方法来维护双向链表的完整性。这些回调方法在 HashMap 的关键操作中被调用，使 LinkedHashMap 能够在不破坏原有功能的基础上维护元素顺序。</p><h3 id="_4-2-核心维护方法详解" tabindex="-1">4.2 核心维护方法详解 <a class="header-anchor" href="#_4-2-核心维护方法详解" aria-label="Permalink to &quot;4.2 核心维护方法详解&quot;">​</a></h3><p>LinkedHashMap 重写了 HashMap 中定义的四个关键回调方法，这些方法构成了维护双向链表的核心机制。下面详细解释每个方法的重写逻辑：</p><h4 id="_1-newnode-方法重写逻辑" tabindex="-1">1. newNode() 方法重写逻辑 <a class="header-anchor" href="#_1-newnode-方法重写逻辑" aria-label="Permalink to &quot;1. newNode() 方法重写逻辑&quot;">​</a></h4><p><code>newNode()</code> 方法负责创建新的节点并将其链接到双向链表中：</p><ul><li><strong>创建节点</strong>：创建一个 <code>LinkedHashMap.Entry</code> 类型的节点，该节点继承自 <code>HashMap.Node</code> 并添加了 <code>before</code> 和 <code>after</code> 指针</li><li><strong>链接到链表尾部</strong>：调用 <code>linkNodeLast()</code> 方法将新节点链接到双向链表的尾部</li><li><strong>返回节点</strong>：将新创建的节点返回给 HashMap 的插入逻辑</li></ul><p>这个方法确保了每次创建新节点时，该节点都会被正确地添加到维护顺序的双向链表中，是链表构建的起点。</p><h4 id="_2-afternodeaccess-方法重写逻辑" tabindex="-1">2. afterNodeAccess() 方法重写逻辑 <a class="header-anchor" href="#_2-afternodeaccess-方法重写逻辑" aria-label="Permalink to &quot;2. afterNodeAccess() 方法重写逻辑&quot;">​</a></h4><p><code>afterNodeAccess()</code> 方法在元素被访问（如 <code>get()</code> 或 <code>put()</code> 操作已存在的键）后被调用：</p><ul><li><strong>条件判断</strong>：首先检查 <code>accessOrder</code> 标志是否为 <code>true</code>，只有在访问顺序模式下才执行后续操作</li><li><strong>移除当前节点</strong>：调用 <code>unlink()</code> 方法将当前节点从双向链表中移除，但不从哈希表中删除</li><li><strong>链接到尾部</strong>：调用 <code>linkNodeLast()</code> 方法将节点重新链接到双向链表的尾部</li><li><strong>更新引用</strong>：更新相关节点的 <code>before</code> 和 <code>after</code> 引用，确保链表的完整性</li></ul><p>这个方法实现了访问顺序模式的核心功能，使得最近访问的元素总是位于链表尾部，方便实现 LRU 缓存策略。</p><h4 id="_3-afternodeinsertion-方法重写逻辑" tabindex="-1">3. afterNodeInsertion() 方法重写逻辑 <a class="header-anchor" href="#_3-afternodeinsertion-方法重写逻辑" aria-label="Permalink to &quot;3. afterNodeInsertion() 方法重写逻辑&quot;">​</a></h4><p><code>afterNodeInsertion()</code> 方法在新元素插入完成后被调用：</p><ul><li><strong>判断是否需要移除</strong>：调用 <code>removeEldestEntry()</code> 方法判断是否需要移除最老的元素</li><li><strong>移除策略</strong>：当 <code>removeEldestEntry()</code> 返回 <code>true</code> 时，移除链表头部（head）的节点</li><li><strong>默认行为</strong>：<code>removeEldestEntry()</code> 方法默认返回 <code>false</code>，即默认不会移除任何元素</li><li><strong>缓存实现</strong>：子类可以通过重写 <code>removeEldestEntry()</code> 方法来定义自己的淘汰策略，如 LRU 缓存中的容量限制</li></ul><p>这个方法为实现缓存淘汰机制提供了钩子，是 LinkedHashMap 能够便捷实现 LRU 缓存的关键所在。</p><h4 id="_4-afternoderemoval-方法重写逻辑" tabindex="-1">4. afterNodeRemoval() 方法重写逻辑 <a class="header-anchor" href="#_4-afternoderemoval-方法重写逻辑" aria-label="Permalink to &quot;4. afterNodeRemoval() 方法重写逻辑&quot;">​</a></h4><p><code>afterNodeRemoval()</code> 方法在元素从哈希表中删除后被调用：</p><ul><li><strong>移除节点</strong>：调用 <code>unlink()</code> 方法将节点从双向链表中移除</li><li><strong>调整引用</strong>：更新被删除节点前后节点的引用关系，确保链表的连续性</li><li><strong>保持完整性</strong>：确保删除操作不会破坏双向链表的结构，维护链表的正确性</li></ul><p>这个方法确保了当元素从哈希表中删除时，对应的节点也会从双向链表中移除，保持两种数据结构的一致性。</p><h3 id="_4-3-链表操作细节" tabindex="-1">4.3 链表操作细节 <a class="header-anchor" href="#_4-3-链表操作细节" aria-label="Permalink to &quot;4.3 链表操作细节&quot;">​</a></h3><ul><li><strong>链表头部（head）</strong>：指向链表中的第一个节点，代表最早插入或最久未访问的元素</li><li><strong>链表尾部（tail）</strong>：指向链表中的最后一个节点，代表最近插入或最近访问的元素</li><li><strong>节点移动流程</strong>：当需要将节点移动到链表尾部时，首先从当前位置移除，然后链接到尾部</li><li><strong>链表完整性</strong>：每次修改操作后，都会确保链表的前后引用关系正确，保持链表的完整性</li></ul><h2 id="_5-排序模式" tabindex="-1">5. 排序模式 <a class="header-anchor" href="#_5-排序模式" aria-label="Permalink to &quot;5. 排序模式&quot;">​</a></h2><h3 id="_5-1-插入顺序模式" tabindex="-1">5.1 插入顺序模式 <a class="header-anchor" href="#_5-1-插入顺序模式" aria-label="Permalink to &quot;5.1 插入顺序模式&quot;">​</a></h3><p>当 <code>accessOrder = false</code>（默认值）时，LinkedHashMap 维护元素的插入顺序：</p><ul><li>元素的迭代顺序与它们被插入到 Map 中的顺序一致</li><li>对于已存在的键，重新设置值不会改变其在链表中的位置</li><li>适用于需要按照操作顺序处理元素的场景</li></ul><h3 id="_5-2-访问顺序模式" tabindex="-1">5.2 访问顺序模式 <a class="header-anchor" href="#_5-2-访问顺序模式" aria-label="Permalink to &quot;5.2 访问顺序模式&quot;">​</a></h3><p>当 <code>accessOrder = true</code> 时，LinkedHashMap 维护元素的访问顺序：</p><ul><li>每次访问（get、containsKey）元素后，该元素会被移到链表尾部</li><li>新插入的元素始终位于链表尾部</li><li>链表头部的元素是最久未被访问的（Least Recently Used，LRU）</li><li>链表尾部的元素是最近被访问的（Most Recently Used，MRU）</li><li>适用于实现 LRU 缓存等需要基于访问频率淘汰元素的场景</li></ul><h2 id="_6-lru-缓存实现原理" tabindex="-1">6. LRU 缓存实现原理 <a class="header-anchor" href="#_6-lru-缓存实现原理" aria-label="Permalink to &quot;6. LRU 缓存实现原理&quot;">​</a></h2><p>LinkedHashMap 提供了一个便捷的方式来实现 LRU（Least Recently Used）缓存：</p><ul><li>设置 <code>accessOrder = true</code> 启用访问顺序维护</li><li>重写 <code>removeEldestEntry(Map.Entry&lt;K, V&gt; eldest)</code> 方法定义淘汰策略</li></ul><p>当 <code>removeEldestEntry()</code> 返回 true 时，链表头部的最久未使用元素将被自动移除。通过在该方法中判断当前元素数量是否超过设定的容量，可以实现固定大小的 LRU 缓存。</p><h2 id="_8-应用场景" tabindex="-1">8. 应用场景 <a class="header-anchor" href="#_8-应用场景" aria-label="Permalink to &quot;8. 应用场景&quot;">​</a></h2><h3 id="_8-1-适合使用-linkedhashmap-的场景" tabindex="-1">8.1 适合使用 LinkedHashMap 的场景 <a class="header-anchor" href="#_8-1-适合使用-linkedhashmap-的场景" aria-label="Permalink to &quot;8.1 适合使用 LinkedHashMap 的场景&quot;">​</a></h3><ul><li><strong>需要保持插入顺序的映射</strong>：如日志记录、历史记录等</li><li><strong>LRU 缓存实现</strong>：通过访问顺序模式和 removeEldestEntry 方法</li><li><strong>需要按操作顺序处理元素</strong>：如请求处理队列、任务调度等</li><li><strong>频繁遍历操作</strong>：相比 HashMap，顺序遍历性能更优</li></ul><h3 id="_8-2-使用注意事项" tabindex="-1">8.2 使用注意事项 <a class="header-anchor" href="#_8-2-使用注意事项" aria-label="Permalink to &quot;8.2 使用注意事项&quot;">​</a></h3><ul><li><strong>线程安全</strong>：非线程安全，多线程环境下可使用 <code>Collections.synchronizedMap()</code> 或考虑使用 <code>ConcurrentHashMap</code></li><li><strong>容量设置</strong>：对于 LRU 缓存实现，合理设置初始容量可减少扩容操作</li><li><strong>内存开销</strong>：比 HashMap 占用更多内存，对于大型集合需考虑内存消耗</li><li><strong>遍历性能</strong>：虽然遍历性能优于 HashMap，但仍需注意大型集合的遍历开销</li></ul>',58)])])}const g=e(l,[["render",i]]);export{u as __pageData,g as default};
